import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"旅","description":"东坡易传 - 旅","frontmatter":{"title":"旅","description":"东坡易传 - 旅"},"headers":[],"relativePath":"zh/classics/dongpo/057.md","filePath":"zh/classics/dongpo/057.md"}'),o={name:"zh/classics/dongpo/057.md"};function r(n,p,c,_,i,d){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="旅" tabindex="-1">旅 <a class="header-anchor" href="#旅" aria-label="Permalink to “旅”">​</a></h1><p>“旅”：小亨，旅貞吉。</p><p>《彖》曰：“旅，小亨”，柔得中乎，外而順乎剛；止而麗乎明；是以“小亨，旅貞吉”也。旅之時義大矣哉！</p><p>“旅”，六二、六五二陰據用事之地，而九三、九四、上九三陽寓於其間，所以爲“旅”也。小者爲主，而大者爲旅。爲主者以得中，而順乎剛爲亨，故曰“小亨”；爲旅者以居貞，而不取爲吉，故曰“旅貞吉”。“止而麗乎明”，則居貞而不取之謂也；“貞吉”者指三陽，非二陰爲主者之事也，故特曰“旅貞吉”。</p><p>象曰：山上有火，“旅”，君子以明慎用刑，而不留獄。</p><p>初六：旅瑣瑣，斯其所取災。象曰：“旅瑣瑣”，志窮災也。</p><p>“羈旅”之世，物無正主，近則相依。自六二至上九，皆陰陽相鄰，而初獨孑然處六二之下，其細已甚①，故曰“旅瑣瑣”也。斯，隸也；六二近於九三，三之所取也；初六窮而無依，隸於六二，役於九三。三“焚”二次，並以及初，故曰“斯其所取災”也。</p><p>【校注】 ① 已甚：《蘇氏易傳》作“以甚”，誤。</p><p>六二：旅即次，懷其資，得童僕，貞。象曰：“得童僕，貞”，終無尤也。</p><p>六二，九三之所即以爲次也。因三之資以隸初六，故曰“得童僕，貞”。初六雖四之應，而四爲三所隔，終“無尤”之者也。</p><p>九三：旅焚其次，喪其童僕，貞厲。象曰：“旅焚其次”，亦以傷矣；以旅與下，其義喪也。</p><p>“下”，初六也。六二，我之次也。而初隸於二，懷二而並有之，則初亦我之童僕矣。九三以剛居上，見得而忘義，焚二以取初，則一舉而兩失之矣。</p><p>九四：旅於處，得其資斧，我心不快。象曰：“旅於處”，未得位也。“得其資斧”，心未快也。</p><p>“資斧”，所以除荊棘、治次舍也。九四剛而失位，所乘者九三，有資斧而無地者也，故處而“心不快”。</p><p>六五：射雉一矢，亡；終以譽命。象曰：“終以譽命”，上逮也。</p><p>居二陽之間，可以德懷，不可以力取。如以一矢射兩雉，理無兼獲。得四則失上矣，若不志於取，亡矢而不射，則夫二陽者皆可以其功譽而爵命之，非獨得四可以及上也。</p><p>上九：鳥焚其巢，旅人先笑後號咷。喪牛於易，兇。象曰：以旅在上，其義焚也。“喪牛於易”，終莫之聞也。</p><p>九三次於六二之上，上九“巢”於六五之上，皆以剛臨柔。六二、六五皆無應，而在我下，其勢必與我。上九、九三知其無應而必我與也，故易而取之。九三“焚其次”，上九“焚其巢”，其爲不義一也。而三止於“貞厲”，上至於“號咷”之兇者，六五旅之主也。“離”之象曰“畜牝牛，吉。”六五之謂牛矣，易五以喪牛，終莫之聞者，驕亢之罪也。</p>',18)])])}const m=a(o,[["render",r]]);export{h as __pageData,m as default};
